# 选项应用需求

本题验证构建配置、路由注册和跨页面通信，需要最小应用结构。首页同时承载样式示例；选择页用于 ready 通知和确认回传；packageA/index.mpx 只用于验证分包路由，已由执行器复制，不必修改。

- 红、蓝卡片的同名类不能相互覆盖；240px 横排中的两个 layout-cell 各占 120px。
- 两个 theme-card 保留调用方 warm-tone、cool-tone 颜色和 spaced-label 的 12px 内边距，以及默认外部类约定。
- Web 的 200rpx 示例块在 375px 和 750px 视口都显示为 100 CSS px，28rpx 字号显示为 14 CSS px；微信尺寸不变。
- 点击首页选择按钮先显示“正在选择”，确认后回传所选文案；navigator 直接进入选择页仍可使用。
- 微信保留胶囊布局；Web 不执行微信胶囊 API，且自定义导航不与系统导航重复显示。
- Web 使用 history 路由，页面和静态资源的部署前缀为 /help-demo/；保留主包、分包页面注册和微信独立分包配置。
module.exports = {
  pluginOptions: {
    mpx: {
      plugin: { srcMode: 'wx' }
    }
  }
}
<script>
import mpx, { createApp } from '@mpxjs/core'
import apiProxy from '@mpxjs/api-proxy'

mpx.use(apiProxy)
createApp({})
</script>
<script type="application/json">
{
  "pages": ["./pages/home/index.mpx", "./pages/choice/index.mpx"],
  "window": { "navigationStyle": "custom" },
  "subpackages": [
    { "root": "packageA", "pages": ["./index.mpx"], "independent": true }
  ]
}
</script>
<template>
  <view class="page">
    <view class="header" style="padding-top: {{topInset}}px; {{headerHeight === null ? '' : 'height: ' + headerHeight + 'px;'}}">
      <text>我的选项</text>
    </view>

    <red-card />
    <blue-card />
    <theme-card label="暖色标签" tone-class="warm-tone" custom-class="spaced-label" />
    <theme-card label="冷色标签" tone-class="cool-tone" custom-class="spaced-label" />
    <view class="equal-row">
      <layout-cell label="甲" />
      <layout-cell label="较长的乙" />
    </view>

    <view class="content">
      <text>当前：{{selectedLabel}}</text>
      <button bindtap="openChoice">选择</button>
      <navigator url="/pages/choice/index?source=link" open-type="navigate">通过链接选择</navigator>
      <navigator url="/packageA/index" open-type="navigate">独立入口</navigator>
      <view class="size-sample">设计宽 200rpx、字体 28rpx</view>
    </view>
  </view>
</template>
<script>
import { createPage } from '@mpxjs/core'

createPage({
  data: { topInset: 0, headerHeight: null, selectedLabel: '未选择' },
  onLoad () {
    const capsule = wx.getMenuButtonBoundingClientRect()
    this.topInset = capsule.top
    this.headerHeight = capsule.height
  },
  methods: {
    openChoice () {
      wx.navigateTo({
        url: '/pages/choice/index',
        events: {
          ready: () => { this.selectedLabel = '正在选择' }
        }
      })
    },
    receiveChoice (label) {
      this.selectedLabel = label
    }
  }
})
</script>
<style>
.page { min-height: 100%; background: #f6f7f9; }
.header { padding-left: 16px; background: #fff; }
.content { padding: 24rpx; }
.size-sample { width: 200rpx; font-size: 28rpx; background: #dde8ff; }

.warm-tone { color: #bb3311; }
.cool-tone { color: #2255cc; }
.spaced-label { padding: 12px; }
.equal-row { display: flex; width: 240px; }
</style>

<script type="application/json">
{
  "usingComponents": {
    "red-card": "../../components/red-card.mpx",
    "blue-card": "../../components/blue-card.mpx",
    "layout-cell": "../../components/layout-cell.mpx",
    "theme-card": "../../components/theme-card.mpx"
  }
}
</script>
<template>
  <view>
    <text>选择一个选项</text>
    <button bindtap="confirm('选项 A')">选项 A</button>
    <button bindtap="confirm('选项 B')">选项 B</button>
  </view>
</template>
<script>
import { createPage, onLoad } from '@mpxjs/core'

createPage({
  setup (props, { getOpenerEventChannel }) {
    onLoad(query => {
      // 普通链接入口没有注册 ready 监听。
      if (query.source !== 'link') getOpenerEventChannel().emit('ready')
    })
    return {
      confirm (label) {
        const pages = getCurrentPages()
        pages[pages.length - 2].receiveChoice(label)
        wx.navigateBack({ delta: 1 })
      }
    }
  }
})
</script>

